from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CENT = Decimal("0.01")
_FOUR = Decimal("0.0001")
_TYPES = {"PURCHASE", "SALE", "CUSTOMER_RETURN", "PURCHASE_RETURN"}


def _quantize(value, exp):
    # Use prec large enough to hold value exactly plus exponent handling
    # determine digits needed
    try:
        digits = len(value.as_tuple().digits)
    except Exception:
        digits = 50
    # exponent can require extra precision when quantizing very large numbers
    # ensure prec > digits - exp (exp is negative)
    # exp exponent: -2 for cent, -4 for 4dp
    exp_digits = -exp.as_tuple().exponent if exp.as_tuple().exponent < 0 else 0
    needed = digits + exp_digits + 10
    # also consider exponent of value
    e = value.as_tuple().exponent
    if e < 0:
        needed += -e
    # floor at 100 to be safe for small numbers, extend if needed
    prec = max(100, needed)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.Emax = 999999999
        ctx.Emin = -999999999
        return value.quantize(exp, rounding=ROUND_HALF_UP)


def _d2(value):
    return _quantize(value, _CENT)


def _div_prec50(a, b):
    with localcontext() as ctx:
        ctx.prec = 50
        ctx.Emax = 999999999
        ctx.Emin = -999999999
        return a / b


def _mul_high(a, b):
    # exact multiplication with enough precision
    try:
        da = len(a.as_tuple().digits)
    except Exception:
        da = 50
    # b may be int or Decimal
    if isinstance(b, int):
        db = len(str(abs(b))) if b != 0 else 1
        b_dec = Decimal(b)
    else:
        db = len(b.as_tuple().digits)
        b_dec = b
    needed = da + db + 10
    # also account for exponents
    try:
        exp_a = a.as_tuple().exponent
        exp_b = b_dec.as_tuple().exponent
        if exp_a < 0:
            needed += -exp_a
        if exp_b < 0:
            needed += -exp_b
    except Exception:
        pass
    prec = max(100, needed)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.Emax = 999999999
        ctx.Emin = -999999999
        return a * b_dec


def _add_high(a, b):
    try:
        da = len(a.as_tuple().digits)
    except Exception:
        da = 50
    try:
        db = len(b.as_tuple().digits)
    except Exception:
        db = 50
    needed = max(da, db) + 10
    # account for exponents difference
    try:
        exp_a = a.as_tuple().exponent
        exp_b = b.as_tuple().exponent
        if exp_a < 0:
            needed += -exp_a
        if exp_b < 0:
            needed += -exp_b
    except Exception:
        pass
    prec = max(100, needed)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.Emax = 999999999
        ctx.Emin = -999999999
        return a + b


def _sub_high(a, b):
    try:
        da = len(a.as_tuple().digits)
    except Exception:
        da = 50
    try:
        db = len(b.as_tuple().digits)
    except Exception:
        db = 50
    needed = max(da, db) + 10
    try:
        exp_a = a.as_tuple().exponent
        exp_b = b.as_tuple().exponent
        if exp_a < 0:
            needed += -exp_a
        if exp_b < 0:
            needed += -exp_b
    except Exception:
        pass
    prec = max(100, needed)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.Emax = 999999999
        ctx.Emin = -999999999
        return a - b


def process_inventory(movements: list[dict]) -> dict:
    if not isinstance(movements, list):
        raise ValueError("movements must be a list")
    qty = 0
    value = Decimal("0.00")
    total_cogs = Decimal("0.00")
    total_pr = Decimal("0.00")
    for mv in movements:
        if not isinstance(mv, dict):
            raise ValueError("movement must be a dict")
        mtype = mv.get("type")
        if mtype not in _TYPES:
            raise ValueError(f"invalid movement type: {mtype!r}")
        quantity = mv.get("quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity must be a positive int")
        if mtype == "PURCHASE":
            if "unit_cost" not in mv:
                raise ValueError("unit_cost required for PURCHASE")
            raw = mv["unit_cost"]
            if not isinstance(raw, str):
                raise ValueError("unit_cost must be a string")
            try:
                cost = Decimal(raw)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid unit_cost: {raw!r}") from None
            if not cost.is_finite() or cost < 0:
                raise ValueError("unit_cost must be finite and >= 0")
            # quantity * unit_cost quantized to cents, with high precision
            prod = _mul_high(cost, quantity)
            added = _d2(prod)
            value = _d2(_add_high(value, added))
            qty += quantity
        elif mtype == "SALE":
            if quantity > qty:
                raise ValueError("sale exceeds quantity on hand")
            avg = _div_prec50(value, qty)
            prod = _mul_high(avg, quantity)
            cogs = _d2(prod)
            value = _d2(_sub_high(value, cogs))
            qty -= quantity
            total_cogs = _d2(_add_high(total_cogs, cogs))
        elif mtype == "CUSTOMER_RETURN":
            if qty == 0:
                raise ValueError("no current average cost for customer return")
            avg = _div_prec50(value, qty)
            prod = _mul_high(avg, quantity)
            added = _d2(prod)
            value = _d2(_add_high(value, added))
            qty += quantity
        else:  # PURCHASE_RETURN
            if quantity > qty:
                raise ValueError("purchase return exceeds quantity on hand")
            avg = _div_prec50(value, qty)
            prod = _mul_high(avg, quantity)
            removed = _d2(prod)
            value = _d2(_sub_high(value, removed))
            qty -= quantity
            total_pr = _d2(_add_high(total_pr, removed))
    if qty == 0:
        avg_out = Decimal("0.0000")
    else:
        div = _div_prec50(value, qty)
        avg_out = _quantize(div, _FOUR)
    return {
        "quantity_on_hand": qty,
        "inventory_value": _d2(value),
        "average_cost": avg_out,
        "total_cogs": _d2(total_cogs),
        "total_purchase_returns": _d2(total_pr),
    }
